import os
from typing import Any, Dict, List, Optional, Tuple

import boto3


def _bbox(block: Dict[str, Any]) -> Dict[str, float]:
    bb = block.get("Geometry", {}).get("BoundingBox", {})
    return {
        "left": float(bb.get("Left", 0.0)),
        "top": float(bb.get("Top", 0.0)),
        "width": float(bb.get("Width", 0.0)),
        "height": float(bb.get("Height", 0.0)),
    }


def _polygon(block: Dict[str, Any]) -> List[Dict[str, float]]:
    pts = block.get("Geometry", {}).get("Polygon", []) or []
    return [{"x": float(p.get("X", 0.0)), "y": float(p.get("Y", 0.0))} for p in pts]


def _cell_text(cell_block: Dict[str, Any], blocks_by_id: Dict[str, Dict[str, Any]]) -> str:
    texts: List[str] = []
    for rel in cell_block.get("Relationships", []) or []:
        if rel.get("Type") != "CHILD":
            continue
        for child_id in rel.get("Ids", []) or []:
            child = blocks_by_id.get(child_id)
            if not child:
                continue
            if child.get("BlockType") == "WORD":
                texts.append(child.get("Text", ""))
            elif child.get("BlockType") == "SELECTION_ELEMENT":
                if child.get("SelectionStatus") == "SELECTED":
                    texts.append("X")
    return " ".join(t for t in texts if t).strip()


def _load_document_bytes(
    file_path: Optional[str] = None,
    document_bytes: Optional[bytes] = None,
) -> bytes:
    if document_bytes is not None:
        return document_bytes
    if file_path is None:
        raise ValueError("Provide either file_path or document_bytes")
    with open(file_path, "rb") as f:
        return f.read()


def extract_tables_and_rows(
    file_path: Optional[str] = None,
    document_bytes: Optional[bytes] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    doc_bytes = _load_document_bytes(file_path=file_path, document_bytes=document_bytes)

    client = boto3.client(
        "textract",
        region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1",
    )

    response = client.analyze_document(
        Document={"Bytes": doc_bytes},
        FeatureTypes=["TABLES"],
    )

    blocks = response.get("Blocks", []) or []
    blocks_by_id: Dict[str, Dict[str, Any]] = {
        b["Id"]: b for b in blocks if "Id" in b
    }

    tables: List[Dict[str, Any]] = []

    for block in blocks:
        if block.get("BlockType") != "TABLE":
            continue

        table_cells: List[Dict[str, Any]] = []
        merged_cells: List[Dict[str, Any]] = []

        child_ids: List[str] = []
        for rel in block.get("Relationships", []) or []:
            if rel.get("Type") == "CHILD":
                child_ids.extend(rel.get("Ids", []) or [])
            elif rel.get("Type") == "MERGED_CELL":
                for merged_id in rel.get("Ids", []) or []:
                    merged = blocks_by_id.get(merged_id)
                    if merged and merged.get("BlockType") == "MERGED_CELL":
                        merged_cells.append(
                            {
                                "id": merged.get("Id"),
                                "row_index": merged.get("RowIndex"),
                                "column_index": merged.get("ColumnIndex"),
                                "row_span": merged.get("RowSpan", 1),
                                "column_span": merged.get("ColumnSpan", 1),
                                "text": _cell_text(merged, blocks_by_id),
                                "confidence": merged.get("Confidence"),
                                "bounding_box": _bbox(merged),
                                "polygon": _polygon(merged),
                            }
                        )

        for child_id in child_ids:
            child = blocks_by_id.get(child_id)
            if not child or child.get("BlockType") != "CELL":
                continue

            entity_types = child.get("EntityTypes", []) or []
            cell = {
                "id": child.get("Id"),
                "row_index": int(child.get("RowIndex", 0)),
                "column_index": int(child.get("ColumnIndex", 0)),
                "row_span": int(child.get("RowSpan", 1)),
                "column_span": int(child.get("ColumnSpan", 1)),
                "text": _cell_text(child, blocks_by_id),
                "confidence": child.get("Confidence"),
                "is_column_header": "COLUMN_HEADER" in entity_types,
                "is_title": "TABLE_TITLE" in entity_types,
                "is_footer": "TABLE_FOOTER" in entity_types,
                "bounding_box": _bbox(child),
                "polygon": _polygon(child),
            }
            table_cells.append(cell)

        table_cells.sort(key=lambda c: (c["row_index"], c["column_index"]))

        rows_map: Dict[int, List[Dict[str, Any]]] = {}
        for cell in table_cells:
            rows_map.setdefault(cell["row_index"], []).append(cell)

        rows: List[Dict[str, Any]] = []
        for row_index in sorted(rows_map):
            cells = sorted(rows_map[row_index], key=lambda c: c["column_index"])
            rows.append(
                {
                    "row_index": row_index,
                    "cells": cells,
                    "text": " | ".join(cell["text"] for cell in cells),
                }
            )

        tables.append(
            {
                "id": block.get("Id"),
                "confidence": block.get("Confidence"),
                "bounding_box": _bbox(block),
                "polygon": _polygon(block),
                "row_count": len(rows),
                "cell_count": len(table_cells),
                "cells": table_cells,
                "rows": rows,
                "merged_cells": merged_cells,
            }
        )

    return {
        "provider": "amazon-textract",
        "model_family": "AnalyzeDocument",
        "tables": tables,
        "table_count": len(tables),
        "raw_block_count": len(blocks),
    }
